create global temporary table xxventuri.crm_accounts_temp (
    unique_id        number,
    customer_id      varchar2(255 byte),
    customer_name    varchar2(255 byte),
    gst_no           varchar2(100 byte),
    credit_terms_rec number,
    contact_id       number,
    contact_name     varchar2(255 byte),
    contact_email    varchar2(255 byte),
    contact_phone    varchar2(255 byte),
    contact_cell     varchar2(255 byte),
    bank_name        number,
    branch_location  varchar2(255 byte),
    account_number   number,
    ifsc_code        varchar2(50 byte),
    staff_code       varchar2(255 byte),
    credit_limit_rec number
) on commit delete rows;


